import{_ as n,C as s,o as l,c as i,E as o,a2 as t}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Weekly 002 — 数字员工控制面与工作 Runtime","description":"","frontmatter":{"title":"Weekly 002 — 数字员工控制面与工作 Runtime","date":"2026-08-01","column":"digital-employee","category":"weekly","summary":"综合 Workday Agent System of Record、OpenHands Agent Canvas 与 CodeFlowMu 的工程方向。","outline":"deep","cover":"/assets/covers/weekly-002-cover-v2.jpg"},"headers":[],"relativePath":"zh/research/weekly/weekly-002.md","filePath":"zh/research/weekly/weekly-002.md","lastUpdated":1787407830000}'),p={name:"zh/research/weekly/weekly-002.md"};function r(d,a,c,u,h,m){const e=s("ArticleCover");return l(),i("div",null,[o(e,{image:"/assets/covers/weekly-002-cover-v2.jpg",kicker:"研究周报 · 002",title:"数字员工控制面与工作 Runtime",summary:"综合 Workday Agent System of Record、OpenHands Agent Canvas 与 CodeFlowMu 的工程方向。",version:"W002",status:"发布于 2026-08-01",languageHref:"/en/research/weekly/weekly-002",languageLabel:"English"}),a[0]||(a[0]=t(`<h2 id="核心综合" tabindex="-1">核心综合 <a class="header-anchor" href="#核心综合" aria-label="Permalink to &quot;核心综合&quot;">​</a></h2><p>第二期研究从“数字员工是什么”推进到两个系统层次的明确分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数字员工控制面</span></span>
<span class="line"><span>  身份、所有权、岗位、权限、名册、</span></span>
<span class="line"><span>  生命周期、政策、成本、遥测与评估</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数字员工工作 Runtime</span></span>
<span class="line"><span>  WorkOrder、规划、工作流、Session、工具、</span></span>
<span class="line"><span>  Checkpoint、恢复、证据与完成门禁</span></span></code></pre></div><p>企业平台通常具备较强的数字劳动力管理能力，但基础设施和组织成本很重；Agent 框架提供执行能力，却常常缺少组织所有权、完成权威和生命周期治理。CodeFlowMu 的机会，是把轻量控制面连接到已经存在的工作 Runtime。</p><h2 id="workday-控制面对标" tabindex="-1">Workday：控制面对标 <a class="header-anchor" href="#workday-控制面对标" aria-label="Permalink to &quot;Workday：控制面对标&quot;">​</a></h2><p>Workday Agent System of Record 把 Agent 当作企业内需要长期治理的资源。真正重要的字段不只是模型和 Prompt，还包括：</p><ul><li>组织负责人；</li><li>角色与技能；</li><li>权限和数据访问；</li><li>Provider 与部署；</li><li>使用量、遥测和工作历史；</li><li>成本与价值；</li><li>合规和生命周期。</li></ul><p>对 CodeFlowMu 最重要的启发是“持久身份”：数字员工不能随着模型 Session 结束而消失，也不能被某个 Provider 绑定。</p><h2 id="openhands-操作者工作空间对标" tabindex="-1">OpenHands：操作者工作空间对标 <a class="header-anchor" href="#openhands-操作者工作空间对标" aria-label="Permalink to &quot;OpenHands：操作者工作空间对标&quot;">​</a></h2><p>OpenHands Agent Canvas 展示了 Agent 长期运行所需要的工程外壳：</p><ul><li>Skill 与 Plugin 可见；</li><li>连接健康诊断；</li><li>启动和运行日志；</li><li>本地、远程与托管执行；</li><li>手动、定时和事件触发；</li><li>面向操作者的工作空间。</li></ul><p>CodeFlowMu 应学习这些运行机制，但不能把产品第一抽象从岗位退回到通用 Agent Workspace。</p><h2 id="codeflowmu-目标结构" tabindex="-1">CodeFlowMu 目标结构 <a class="header-anchor" href="#codeflowmu-目标结构" aria-label="Permalink to &quot;CodeFlowMu 目标结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>组织</span></span>
<span class="line"><span>  ↓ 定义</span></span>
<span class="line"><span>岗位</span></span>
<span class="line"><span>  ↓ 注册到</span></span>
<span class="line"><span>数字员工控制面</span></span>
<span class="line"><span>  ↓ 生成</span></span>
<span class="line"><span>WorkOrder</span></span>
<span class="line"><span>  ↓ 由</span></span>
<span class="line"><span>CodeFlowMu 工作 Runtime 执行</span></span>
<span class="line"><span>  ↓ 使用</span></span>
<span class="line"><span>Agent Provider + 工具 + 规则 + 人类</span></span>
<span class="line"><span>  ↓ 形成</span></span>
<span class="line"><span>TMPA / FCoP 治理的 Outcome</span></span></code></pre></div><h3 id="控制面" tabindex="-1">控制面 <a class="header-anchor" href="#控制面" aria-label="Permalink to &quot;控制面&quot;">​</a></h3><ul><li>PositionRegistry；</li><li>DigitalEmployeeRegistry；</li><li>所有权与组织归属；</li><li>TeamPolicy 与权限；</li><li>Provider、工具与凭证绑定；</li><li>生命周期与版本；</li><li>成本、SLA 与评估记录；</li><li>合规与审计视图。</li></ul><h3 id="工作-runtime" tabindex="-1">工作 Runtime <a class="header-anchor" href="#工作-runtime" aria-label="Permalink to &quot;工作 Runtime&quot;">​</a></h3><ul><li>现有 PM 继续作为 Work Manager；</li><li>WorkOrder、Plan 与 Workflow；</li><li>Operation Node；</li><li>SessionManager 与 TaskDispatcher；</li><li>Browser、Windows、Source 与 API 工具；</li><li>Checkpoint、重试与恢复；</li><li>Event Outbox 与 TMPA 投影；</li><li>FCoP 正式协作；</li><li>业务完成与发布完成门禁。</li></ul><h2 id="sme-first-约束" tabindex="-1">SME-first 约束 <a class="header-anchor" href="#sme-first-约束" aria-label="Permalink to &quot;SME-first 约束&quot;">​</a></h2><p>目标不是复制一套大型企业 AI Control Tower，而是实现最小但完整的数字员工平台：本地或小服务可部署、Provider 无关、成本可控、人类保留最终权威、工作证据可以导出和重建。</p><h2 id="建议工程顺序" tabindex="-1">建议工程顺序 <a class="header-anchor" href="#建议工程顺序" aria-label="Permalink to &quot;建议工程顺序&quot;">​</a></h2><ol><li>将现有 Open Dev Team 投影为第一个注册数字员工；</li><li>先增加负责人、岗位、版本、Provider、允许工具、生命周期和成本政策的只读名册；</li><li>验证期间不改变现有 PM/FCoP/Runtime 行为；</li><li>在一个控制台统一展示 Provider、工具、Session、HOLD 与恢复状态；</li><li>在建设完整 Studio 之前，用赛格短租数字员工验证第二个非开发岗位。</li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>未来竞争的系统类别已经不再是“谁拥有更多 Agent”，而是：</p><blockquote><p><strong>受治理的数字劳动力控制面，连接可靠的 AI 工作 Runtime。</strong></p></blockquote><p>CodeFlowMu 的差异化机会，是成为这一类别面向中小企业的轻量工程实现。</p>`,26))])}const y=n(p,[["render",r]]);export{g as __pageData,y as default};
